mkdir -p ~/.config/opencode && cat > ~/.config/opencode/opencode.json <<'EOF'
{
  "$schema": "https://opencode.ai/config.json",
  "model": "obscurify/deepseek/deepseek-v4.1-flash-1017-uncensored",
  "provider": {
    "obscurify": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "obscurify",
      "options": {
        "baseURL": "https://obscurify.ai/v1",
        "apiKey": "{env:OBSCURIFY_API_KEY}"
      },
      "models": {
        "deepseek/deepseek-v4.1-flash-1017-uncensored": {"name": "DeepSeek V4.1 Flash Uncensored"}
      }
    }
  }
}
EOF



cd /tmp && export OBSCURIFY_API_KEY="$(cat ~/.obscurify_key)" && timeout 200 /workspace/project/mf/tools/node_modules/.bin/opencode run --model obscurify/deepseek/deepseek-v4.1-flash-1017-uncensored "Reply with exactly: OK" 2>&1 | tail -12


